from .contiguous import contiguous

logger = logging.getLogger(__name__)

_REGISTER_TILE_LIMIT = 32
# Per-program (batch, n, n) tile element cap for the batched version, and the desired CTA count (12 SIP * 4)
_BATCH_TILE_ELEMENTS = 8192
_TARGET_CTA_COUNT = 48


def _pick_block_batch(block_n: int, batch_count: int) -> int:
    """Choose how many matrices each program handles: too-small batch falls back to the single-matrix kernel (avoiding
    tiles
    full of masked-out empty matrices), otherwise trade tile capacity against CTA count.

    ceil rather than floor decides the per-CTA matrix count: floor yields 64+ CTAs (e.g. 128
    matrices, floor(128/48)=2 -> block_batch=2 -> 64 CTAs), and the extra partial wave drags
    the 16x16 batch from 0.14ms to 0.41ms; ceil gives 128/48->4, i.e. 32 CTAs in exactly one wave.
    """
    capacity = max(1, _BATCH_TILE_ELEMENTS // (block_n * block_n))
    target = triton.next_power_of_2(max(1, -(-batch_count // _TARGET_CTA_COUNT)))
    return max(1, min(capacity, target))


def _pick_num_warps(block_n: int, block_batch: int, element_size: int) -> int:
    """Warp count for the batched kernel, measured per matrix order on GCU400.

    Large n (16) needs many elimination steps and every pivot reduction crosses lanes, so four
    warps are needed to hide the reduction latency; n=8 is fastest with a single warp once the
    batch is large (32 lanes fill one matrix block); n<=4 is extrapolated from the tile size.
    """
    if block_n >= 16:
        # With few matrices per CTA (small tile), more warps are needed to flatten reduction latency; with many
        # matrices,
        # a single CTA already has enough parallelism, and adding warps just makes the 32 CTAs compete for free SPCs.
        return 4 if block_batch <= 8 else 2
    if block_n == 8:
        return 1 if block_batch >= 64 else 2
    return min(8, max(1, (block_batch * block_n * block_n * element_size) // 4096))


@libentry()
@triton.jit
def _logdet_register_kernel(
    inp,
    out,
    n: tl.constexpr,
    block_n: tl.constexpr,
):
    pid = tle.program_id(0)
    rows = tl.arange(0, block_n)
    cols = tl.arange(0, block_n)
    mask = (rows[:, None] < n) & (cols[None, :] < n)
    offsets = pid * n * n + rows[:, None] * n + cols[None, :]
    work = tl.load(inp + offsets, mask=mask, other=0.0)

    swap_count = tl.zeros((), dtype=tl.int32)
    singular = tl.zeros((), dtype=tl.int1)

    for k in range(n):
        column = tl.sum(tl.where(cols[None, :] == k, work, 0.0), axis=1)
        abs_column = tl.where((rows >= k) & (rows < n), tl.abs(column), -float("inf"))
        pivot_abs = tl.max(abs_column, axis=0)
        pivot_row = tl.min(tl.where(abs_column == pivot_abs, rows, block_n), axis=0)
        singular |= pivot_abs == 0.0

        row_k = tl.sum(tl.where(rows[:, None] == k, work, 0.0), axis=0)
        row_p = tl.sum(tl.where(rows[:, None] == pivot_row, work, 0.0), axis=0)
        work = tl.where(rows[:, None] == k, row_p[None, :], work)
        work = tl.where(rows[:, None] == pivot_row, row_k[None, :], work)
        swap_count += pivot_row != k

        column = tl.sum(tl.where(cols[None, :] == k, work, 0.0), axis=1)
        pivot = tl.sum(tl.where(rows == k, column, 0.0), axis=0)
        safe_pivot = tl.where(pivot == 0.0, 1.0, pivot)
        multiplier = tl.where(rows > k, column / safe_pivot, 0.0)
        pivot_row_values = row_p
        update_mask = (rows[:, None] > k) & (cols[None, :] > k)
        update = tl.where(
            multiplier[:, None] == 0.0,
            0.0,
            multiplier[:, None] * pivot_row_values[None, :],
        )
        work = tl.where(
            update_mask,
            work - update,
            work,
        )

    diagonal = tl.sum(tl.where(rows[:, None] == cols[None, :], work, 0.0), axis=0)
    valid_diagonal = cols < n
    singular |= tl.sum(tl.where(valid_diagonal & (diagonal == 0.0), 1, 0), axis=0) > 0
    negative_count = tl.sum(tl.where(valid_diagonal & (diagonal < 0.0), 1, 0), axis=0)
    negative = (negative_count + swap_count) % 2 != 0
    logabsdet = tl.sum(tl.where(valid_diagonal, tl.log(tl.abs(diagonal)), 0.0), axis=0)

    result = tl.where(negative, float("nan"), logabsdet)
    result = tl.where(singular, -float("inf"), result)
    tl.store(out + pid, result)


@triton.jit
def _logdet_batch_register_kernel(
    inp,
    out,
    batch_count,
    n: tl.constexpr,
    block_n: tl.constexpr,
    block_batch: tl.constexpr,
):
    """Process block_batch matrices at once: fold the batch axis into the tile so small matrices (n<=16) can also
    fill the vector width. Elimination steps are identical to the single-matrix version, except all row/column
    extractions degenerate into reductions along axis=1 / axis=2, parallel over the batch axis.
    """
    pid = tle.program_id(0)
    rows = tl.arange(0, block_n)
    cols = tl.arange(0, block_n)
    batch_idx = pid * block_batch + tl.arange(0, block_batch)
    batch_mask = batch_idx < batch_count

    tile_mask = (
        batch_mask[:, None, None]
        & (rows[None, :, None] < n)
        & (cols[None, None, :] < n)
    )
    offsets = (
        batch_idx[:, None, None] * (n * n)
        + rows[None, :, None] * n
        + cols[None, None, :]
    )
    work = tl.load(inp + offsets, mask=tile_mask, other=0.0)

    swap_count = tl.zeros((block_batch,), dtype=tl.int32)
    singular = tl.zeros((block_batch,), dtype=tl.int1)

    for k in range(n):
        # In order: take column k -> select pivot row -> swap -> compute elimination multipliers -> rank-1 update
        column = tl.sum(tl.where(cols[None, None, :] == k, work, 0.0), axis=2)
        abs_column = tl.where(
            (rows[None, :] >= k) & (rows[None, :] < n), tl.abs(column), -float("inf")
        )
        pivot_abs = tl.max(abs_column, axis=1)
        pivot_row = tl.min(
            tl.where(abs_column == pivot_abs[:, None], rows[None, :], block_n), axis=1
        )
        singular |= pivot_abs == 0.0

        row_k = tl.sum(tl.where(rows[None, :, None] == k, work, 0.0), axis=1)
        row_p = tl.sum(
            tl.where(rows[None, :, None] == pivot_row[:, None, None], work, 0.0), axis=1
        )
        work = tl.where(rows[None, :, None] == k, row_p[:, None, :], work)
        work = tl.where(
            rows[None, :, None] == pivot_row[:, None, None], row_k[:, None, :], work
        )
        swap_count += pivot_row != k

        column = tl.sum(tl.where(cols[None, None, :] == k, work, 0.0), axis=2)
        pivot = tl.sum(tl.where(rows[None, :] == k, column, 0.0), axis=1)
        safe_pivot = tl.where(pivot == 0.0, 1.0, pivot)
        multiplier = tl.where(rows[None, :] > k, column / safe_pivot[:, None], 0.0)
        update_mask = (rows[None, :, None] > k) & (cols[None, None, :] > k)
        # Rows with a zero multiplier are explicitly zeroed to avoid 0*inf/NaN polluting the whole row
        update = tl.where(
            multiplier[:, :, None] == 0.0,
            0.0,
            multiplier[:, :, None] * row_p[:, None, :],
        )
        work = tl.where(update_mask, work - update, work)

    diagonal = tl.sum(
        tl.where(rows[None, :, None] == cols[None, None, :], work, 0.0), axis=1
    )
    valid_diagonal = cols[None, :] < n
    singular |= tl.sum(tl.where(valid_diagonal & (diagonal == 0.0), 1, 0), axis=1) > 0
    negative_count = tl.sum(tl.where(valid_diagonal & (diagonal < 0.0), 1, 0), axis=1)
    negative = (negative_count + swap_count) % 2 != 0
    logabsdet = tl.sum(tl.where(valid_diagonal, tl.log(tl.abs(diagonal)), 0.0), axis=1)

    result = tl.where(negative, float("nan"), logabsdet)
    result = tl.where(singular, -float("inf"), result)
    tl.store(out + batch_idx, result, mask=batch_mask)


def logdet(inp):
    logger.debug("GEMS_ENFLAME LOGDET")

    if inp.dim() < 2 or inp.shape[-1] != inp.shape[-2]:
        raise RuntimeError("logdet: input must be batches of square matrices")
    if inp.is_complex():
        raise RuntimeError("logdet: complex inputs are not supported by this kernel")
    if inp.requires_grad:
        raise RuntimeError("logdet: autograd is not supported by this kernel")
    if inp.dtype not in (torch.float32, torch.float64):
        raise RuntimeError(f"logdet: unsupported dtype {inp.dtype}")

    n = inp.shape[-1]
    batch_shape = inp.shape[:-2]
    batch_count = math.prod(batch_shape)

    if n == 0:
        return torch.zeros(batch_shape, dtype=inp.dtype, device=inp.device)
    if batch_count == 0:
        return torch.empty(batch_shape, dtype=inp.dtype, device=inp.device)
    fp64_unsupported = inp.dtype == torch.float64 and n > 16
    if n > _REGISTER_TILE_LIMIT or fp64_unsupported:
        raise RuntimeError(
            f"logdet: {inp.dtype} matrices of size {n} are not supported by "
            "the Triton kernel"
        )

    inp_contiguous = contiguous(inp).reshape(batch_count, n, n)
    out = torch.empty(batch_count, dtype=inp.dtype, device=inp.device)
    block_n = max(2, triton.next_power_of_2(n))
    block_batch = _pick_block_batch(block_n, batch_count)

    with torch_device_fn.device(inp.device):
        if block_batch > 1:
            # Batched version: each program consumes block_batch matrices so small matrices also fill the vector width
            num_warps = _pick_num_warps(block_n, block_batch, inp.element_size())
            _logdet_batch_register_kernel[(triton.cdiv(batch_count, block_batch),)](
                inp_contiguous,
                out,
                batch_count,
                n=n,
                block_n=block_n,
                block_batch=block_batch,
                num_warps=num_warps,
            )
        else:
            num_warps = min(8, max(1, (block_n * block_n * inp.element_size()) // 4096))
            _logdet_register_kernel[(batch_count,)](
                inp_contiguous,
                out,
                n=n,
                block_n=block_n,
                num_warps=num_warps,
            )
    return out.reshape(batch_shape)
